        this.arr[this.rear] = value;
        this.size++;
    }

    dequeue() {
        if (this.isEmpty()) throw new Error("Queue Underflow");
        const value = this.arr[this.front];
        this.front = (this.front + 1) % this.capacity;
        this.size--;
